negativeExample:
import org.eclipse.ui.IWorkbenchSite;
import org.eclipse.ui.services.IServiceLocator;
import org.eclipse.e4.core.contexts.IHandlerService;

class Test {
    public void someMethod(IWorkbenchSite site) {
        IServiceLocator locator = site;
        // Should not match: method is not 'getService'
        Object obj = (Object) locator.someOtherMethod(IHandlerService.class);
        // Should not match: argument is not a class literal
        Object anotherObj = (IHandlerService) locator.getService("IHandlerService");
        // Should not match: cast type (Object) does not match class literal type (IHandlerService)
        Object obj2 = (Object) locator.getService(IHandlerService.class);
        // This *would* match, as cast type and class argument type are both Object. This is a valid application.
        Object obj3 = (Object) locator.getService(Object.class);
    }
}
